header={"Referer":baseUrl};
headers={"headers":JSON.stringify(header)};
imgl=eval(result.match(/(eval\(.+?\}\)\))/)[1]);

host = "http://images.720rs.com";
image=cInfo.fs;
//piclist.map(u=>"<img src=\""+server+u+','+JSON.stringify(headers)+"\">").join("\n")

