    if (image.match(/^(\/Man?)/i)) {
        return host + image
    } else if (image.match(/^(http?)/i)) {
        return image
    }
}
for(i in image){
url=get7ImageUrl(image[i]);
html+='<img src="'+url+','+JSON.stringify(headers)+'">\n'
}
